arguments:
$ErrorActionPreference = 'Stop'
$taskName = 'Codex_Inspect_Cinebench_User_20260904T1555'
$scriptPath = 'C:\Assets\AssetValidation\AssetValidation-20260904T103354\Inspect-CinebenchSignaturesAsUser-20260904T1546.ps1'
$outputPath = 'C:\Assets\AssetValidation\AssetValidation-20260904T103354\cinebench-song-signature-check-20260904T1555.json'
$user = 'DESKTOP-5OJC3K4\Song'
if (-not (Test-Path -LiteralPath $scriptPath -PathType Leaf)) { throw ('Inspection script not found: ' + $scriptPath) }
if (Test-Path -LiteralPath $outputPath) { throw ('Refusing to overwrite: ' + $outputPath) }
$quote = [char]34
$arguments = '-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File ' + $quote + $scriptPath + $quote + ' -OutputPath ' + $quote + $outputPath + $quote
$action = New-ScheduledTaskAction -Execute 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe' -Argument $arguments
$principal = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Limited
$settings = New-ScheduledTaskSettingsSet -ExecutionTimeLimit (New-TimeSpan -Minutes 3) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries
try {
 Register-ScheduledTask -TaskName $taskName -Action $action -Principal $principal -Settings $settings -Force | Out-Null
 Start-ScheduledTask -TaskName $taskName
 $deadline = (Get-Date).AddSeconds(120)
 while ((Get-Date) -lt $deadline -and -not (Test-Path -LiteralPath $outputPath -PathType Leaf)) { Start-Sleep -Seconds 1 }
 if (-not (Test-Path -LiteralPath $outputPath -PathType Leaf)) {
  $info = Get-ScheduledTaskInfo -TaskName $taskName
  throw ('Inspection output was not created. LastTaskResult=' + $info.LastTaskResult)
 }
 Start-Sleep -Seconds 1
 $result = Get-Content -LiteralPath $outputPath -Raw -Encoding UTF8 | ConvertFrom-Json
 'IDENTITY=' + $result.Identity
 'SESSION=' + $result.SessionId
 'FILES:'
 $result.FileResults | Select-Object Copy,RelativePath,Exists,Length,SHA256,Streams,SignatureStatus,SignatureMessage,ChainOk | Format-List
 'DIGICERT_STORES:'
 $result.CertificateStores | ForEach-Object { Write-Output ('STORE=' + $_.Store); $_.Certificates | Select-Object Subject,Issuer,Thumbprint,NotAfter | Format-List }
} finally {
 Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue
}
